create table if not exists public.travel_trips (id uuid primary key default gen_random_uuid(),name text not null,team_id uuid references public.teams(id) on delete set null,location text,start_date date,end_date date,status text not null default 'planning' check(status in('planning','confirmed','completed','cancelled')),tournament_fee numeric not null default 0 check(tournament_fee>=0),transport_cost numeric not null default 0 check(transport_cost>=0),hotel_cost numeric not null default 0 check(hotel_cost>=0),meal_cost numeric not null default 0 check(meal_cost>=0),other_cost numeric not null default 0 check(other_cost>=0),family_charge numeric not null default 0 check(family_charge>=0),notes text,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.travel_participants (trip_id uuid not null references public.travel_trips(id) on delete cascade,player_id uuid not null references public.players(id) on delete cascade,attendance text not null default 'invited' check(attendance in('invited','confirmed','declined')),amount_due numeric not null default 0 check(amount_due>=0),amount_paid numeric not null default 0 check(amount_paid>=0),contact_status text not null default 'not_contacted' check(contact_status in('not_contacted','contacted','confirmed')),room_transport_notes text,updated_at timestamptz not null default now(),primary key(trip_id,player_id));
alter table public.travel_trips enable row level security;alter table public.travel_participants enable row level security;
create policy "admins manage travel trips" on public.travel_trips for all to authenticated using(public.is_owner_admin()) with check(public.is_owner_admin());
create policy "admins manage travel participants" on public.travel_participants for all to authenticated using(public.is_owner_admin()) with check(public.is_owner_admin());
